-- Пояснения к каждому варианту для прежних вопросов тем 05–08.
-- Вопросы ищутся по полному тексту; заполняются только пустые option_notes, повторный запуск безопасен.

BEGIN;

UPDATE questions q SET option_notes = n.notes::jsonb
FROM (VALUES
    ('Что хранит снимок данных?', '{"A":"Снимок не копирует данные: видимость определяется по номерам транзакций.","B":"Буферный кеш общий для всех, снимок его не копирует.","C":"По этим числам решается, какие версии строк видны.","D":"Признаки блокировки хранятся в самих версиях строк, а не в снимке."}'),
    ('Какой уровень изоляции используется в PostgreSQL по умолчанию?', '{"A":"Снимок строится в начале каждого оператора.","B":"Принимается, но работает как Read Committed.","C":"Используется, если выбран явно или задан в default_transaction_isolation.","D":"Используется, если выбран явно или задан в default_transaction_isolation."}'),
    ('Как PostgreSQL ведёт себя на уровне Read Uncommitted?', '{"A":"Грязного чтения в PostgreSQL нет ни на одном уровне.","B":"Уровень принимается, но ведёт себя как Read Committed.","C":"Ошибки нет, уровень принимается.","D":"Ведёт себя как Read Committed, а не Serializable."}'),
    ('Когда строится снимок данных на уровне Repeatable Read?', '{"A":"Так работает Read Committed.","B":"При фиксации снимок уже не нужен.","C":"Снимок относится к транзакции, а не к сеансу.","D":"Снимок строится первым оператором, которому нужны данные (BEGIN его не создаёт), и действует до конца транзакции."}'),
    ('Что физически происходит при UPDATE строки?', '{"A":"Многоверсионность не перезаписывает строку на месте.","B":"Старая версия остаётся, пока её не уберёт очистка.","C":"Создаётся новая версия строки, а не копия страницы.","D":"У старой версии заполняется xmax, а новая версия размещается на той же или другой странице."}'),
    ('Что такое горизонт очистки?', '{"A":"Горизонт — это номер транзакции, а не размер.","B":"Версии, удалённые до горизонта, не нужны ни одному снимку и могут быть вычищены.","C":"Расписание автоочистки — отдельное понятие.","D":"Контрольная точка относится к журналу, а не к видимости версий."}'),
    ('Чем опасна долгая транзакция?', '{"A":"Пока она активна, очистка не может удалить версии строк, нужные её снимку.","B":"Обычные изменения строк не блокируют чтение; чтение таблицы мешает только блокировка ACCESS EXCLUSIVE.","C":"Запись журнала не останавливается.","D":"Накопительная статистика от этого не сбрасывается."}'),
    ('В каком случае транзакция будет ждать освобождения блокировки строки?', '{"A":"Писатели не блокируют читателей: читается подходящая версия строки.","B":"Обычное чтение не ждёт изменений.","C":"Изменить строку можно, когда первая транзакция завершится или откатится к более ранней точке сохранения.","D":"Чтения не блокируют друг друга."}'),
    ('Сколько бит отводится на статус транзакции в clog и где хранятся эти файлы?', '{"A":"Бит не один, а два; pg_wal — каталог журнала предзаписи.","B":"Два бита кодируют четыре состояния транзакции; файлы лежат в pg_xact.","C":"Не восемь бит; в global лежат общие объекты кластера.","D":"Два бита верно, но pg_stat — каталог статистики."}'),
    ('Почему откат транзакции выполняется так же быстро, как фиксация?', '{"A":"Изменения сразу попадают в страницы, они не ждут COMMIT.","B":"Отдельного фонового процесса отката нет.","C":"При откате журналирование не отключается.","D":"В clog ставится статус «прервана»; ненужные версии строк потом уберёт очистка."}'),
    ('На каких уровнях изоляции транзакция может завершиться ошибкой сериализации?', '{"A":"При обычных изменениях ошибок сериализации нет: изменения перепроверяются по свежим данным.","B":"Здесь ошибка возникает и при аномалиях между параллельными транзакциями.","C":"Ошибка возникает при попытке изменить строку, которую после построения снимка изменила и зафиксировала другая транзакция.","D":"Работает как Read Committed, при обычных изменениях ошибок сериализации нет."}'),
    ('Что верно для уровня изоляции Read Committed?', '{"A":"Так работает Repeatable Read.","B":"Каждый оператор видит данные, зафиксированные к его началу, и собственные изменения транзакции.","C":"Грязного чтения в PostgreSQL нет.","D":"Между запросами другие транзакции могут зафиксировать изменения."}'),
    ('Что верно для блокировок в PostgreSQL?', '{"A":"Читатель не ждёт: он видит подходящую версию строки.","B":"Обычные блокировки держатся до конца транзакции или до отката к более ранней точке сохранения; рекомендательные блокировки сеанса — до конца сеанса.","C":"Блокировки строк тоже держатся до конца транзакции или до отката к более ранней точке сохранения.","D":"Обычный SELECT без FOR UPDATE и FOR SHARE не мешает чтению и изменению строк; он конфликтует лишь с ACCESS EXCLUSIVE, например у DDL."}'),
    ('Допишите команду, чтобы все запросы транзакции работали с одним снимком данных:
```
BEGIN ISOLATION LEVEL ___;
```', '{"A":"Снимок строится заново для каждого оператора.","B":"Снимок строится первым оператором, которому нужны данные, и действует до конца транзакции.","C":"Такого уровня изоляции нет.","D":"Работает как Read Committed."}'),
    ('Допишите команду, чтобы получить полную изоляцию, как при последовательном выполнении транзакций:
```
BEGIN;
SET TRANSACTION ISOLATION LEVEL ___;
```', '{"A":"Допускает неповторяющееся чтение и фантомы.","B":"Такого уровня изоляции нет; EXCLUSIVE — режим блокировки.","C":"Зафиксированные транзакции дают результат как при последовательном выполнении; при конфликтах возможны ошибки сериализации.","D":"Не защищает от всех аномалий, например от несогласованной записи."}'),
    ('Допишите запрос, чтобы до конца транзакции другие не могли изменить выбранную строку:
```
SELECT * FROM accounts WHERE id = 1 FOR ___;
```', '{"A":"Блокирует выбранные строки до конца транзакции (или до отката к более ранней точке сохранения).","B":"Такого варианта нет; таблицу целиком блокирует команда LOCK.","C":"Такого варианта нет.","D":"Такого варианта нет."}'),
    ('Что делает очистка (VACUUM) в первую очередь?', '{"A":"Так делает VACUUM FULL.","B":"Обычная очистка место ОС, как правило, не возвращает.","C":"Ненужные файлы WAL удаляются или переиспользуются после контрольной точки.","D":"Освободившееся место используется для новых версий строк."}'),
    ('Для каких объектов существует карта видимости?', '{"A":"У индексов карты видимости нет.","B":"Карта отмечает страницы, где все версии видны всем или заморожены.","C":"У индексов карты видимости нет.","D":"Карта видимости ведётся для таблиц."}'),
    ('Зачем нужна заморозка версий строк?', '{"A":"Замороженную строку можно изменять как обычно.","B":"Заморозка данные не сжимает.","C":"Счётчик транзакций 32-битный и идёт по кругу; замороженная версия считается созданной в прошлом при любом значении счётчика.","D":"К репликации заморозка не относится."}'),
    ('Что произойдёт, если не выполнять заморозку своевременно?', '{"A":"Так сервер защищается от переполнения счётчика транзакций; нужна очистка с заморозкой.","B":"Последствия гораздо серьёзнее: новые транзакции не получат номера.","C":"Старые строки сами не удаляются.","D":"Автоочистка не отключается; защитная очистка запускается даже при выключенной автоочистке."}'),
    ('Отключение какого параметра, кроме autovacuum, останавливает обычную автоочистку?', '{"A":"Без статистики обращений автоочистка не знает, какие таблицы обрабатывать.","B":"Учитывает вызовы функций, на автоочистку не влияет.","C":"Учитывает время ввода-вывода, на автоочистку не влияет.","D":"Отвечает за надёжную запись на диск, а не за автоочистку."}'),
    ('Какой процесс планирует работу автоочистки и запускает рабочие процессы?', '{"A":"Рабочий процесс обрабатывает таблицы, но работу не планирует.","B":"Фоновая запись грязных буферов.","C":"Периодически запускает рабочие процессы для баз данных.","D":"Выполняет контрольные точки."}'),
    ('Какой командой вручную собрать статистику для планировщика?', '{"A":"Перестраивает таблицу и обновляет сведения о её размере, но статистику распределения значений не собирает.","B":"Собирает статистику по выборке строк.","C":"Перестраивает индексы.","D":"Выполняет контрольную точку."}'),
    ('Возвращает ли обычный VACUUM освободившееся место операционной системе?', '{"A":"Обычно нет.","B":"Размер таблицы здесь роли не играет.","C":"Для индексов то же самое.","D":"Системе возвращается только пустой хвост файла."}'),
    ('Чем VACUUM FULL отличается от обычного VACUUM?', '{"A":"Наоборот: требует исключительной блокировки и работает дольше.","B":"Так работает ANALYZE.","C":"Таблица на это время недоступна даже для чтения.","D":"Перестраивает и таблицу, и индексы."}'),
    ('Какое ограничение есть у REINDEX ... CONCURRENTLY?', '{"A":"Не выполняется внутри транзакции и не работает для индексов системного каталога.","B":"Наоборот, изменения таблицы не блокируются.","C":"От автоочистки не зависит.","D":"Обычно работает дольше обычного REINDEX."}'),
    ('Какие задачи выполняет процесс автоочистки?', '{"A":"Удаляет мёртвые версии строк из таблиц и ссылающиеся на них записи из индексов.","B":"Выполняет ANALYZE для изменившихся таблиц.","C":"Отрезает только пустой хвост файла, полностью не сжимает.","D":"Индексы автоочистка не перестраивает."}'),
    ('Что может привести к разрастанию таблиц и индексов?', '{"A":"Контрольные суммы на размер таблиц не влияют.","B":"Могут удерживать горизонт очистки, если держат старый снимок или номер транзакции.","C":"Создают сразу много мёртвых версий строк.","D":"Контрольные точки на размер таблиц не влияют."}'),
    ('Что верно для команды VACUUM FULL?', '{"A":"Таблица перезаписывается без мёртвых версий.","B":"Таблица на это время недоступна.","C":"Таблица заблокирована на всё время перестроения.","D":"Статистику собирает ANALYZE."}'),
    ('Допишите команду, чтобы одной командой выполнить очистку и сбор статистики:
```
VACUUM ___ accounts;
```', '{"A":"Очистка и сбор статистики одной командой.","B":"Агрессивная заморозка; статистику распределения значений не собирает.","C":"Полная перезапись таблицы; статистику распределения значений не собирает.","D":"Такого параметра нет."}'),
    ('Допишите команду ОС, чтобы только собрать статистику без очистки:
```
vacuumdb ___ appdb
```', '{"A":"Выполнит и очистку, и анализ.","B":"Полная очистка с перезаписью таблиц.","C":"Такого ключа нет.","D":"Только анализ, без очистки."}'),
    ('Допишите команду, чтобы перестроить индекс без блокировки изменений таблицы:
```
REINDEX INDEX ___ accounts_pkey;
```', '{"A":"Такого ключевого слова нет.","B":"У REINDEX такого ключевого слова нет.","C":"Такого ключевого слова нет.","D":"Перестраивает индекс, не блокируя изменения таблицы."}'),
    ('Как называется буфер со страницей, изменённой, но ещё не записанной на диск?', '{"A":"Страница изменена в кеше, а на диске пока старая версия.","B":"Замороженными бывают версии строк.","C":"Мёртвыми бывают версии строк.","D":"Закреплённый буфер сейчас используется, и его нельзя вытеснить."}'),
    ('Какую страницу выбирает алгоритм вытеснения из буферного кеша?', '{"A":"Порядок попадания в кеш не учитывается.","B":"Выбор не случайный.","C":"Алгоритм по счётчику обращений приближённо выбирает редко используемые страницы.","D":"Все страницы одного размера."}'),
    ('В чём главное правило журнала предзаписи (WAL)?', '{"A":"Наоборот: сначала журнал, потом данные.","B":"Журнал пишется постоянно, а синхронная фиксация ждёт его сброса на диск.","C":"Журнал записывается на диск, иначе по нему нельзя восстановиться.","D":"Тогда после сбоя изменения можно восстановить по журналу."}'),
    ('В каком каталоге находятся файлы журнала предзаписи?', '{"A":"Здесь хранятся статусы транзакций.","B":"Сегменты журнала лежат в pg_wal.","C":"Здесь общие объекты кластера.","D":"Здесь ссылки на табличные пространства."}'),
    ('Какие таблицы не защищены журналом предзаписи?', '{"A":"Системный каталог журналируется.","B":"Временные исчезают вместе с сеансом, нежурналируемые после сбоя очищаются.","C":"Данные лежат в секциях, обычные секции журналируются.","D":"Обычные таблицы и их индексы журналируются; у UNLOGGED-таблиц индексы тоже не журналируются."}'),
    ('Что делает контрольная точка?', '{"A":"Резервную копию делает pg_basebackup.","B":"Это задача очистки.","C":"Переключение на реплику — отдельная процедура.","D":"После неё восстановление начинается с этой точки."}'),
    ('С какого места начинается восстановление после сбоя?', '{"A":"Журнал до последней контрольной точки не нужен.","B":"Начинают с контрольной точки, а не с транзакции.","C":"Все изменения до неё уже на диске.","D":"Момент запуска с журналом не связан."}'),
    ('Какой процесс записывает журнал на диск в асинхронном режиме?', '{"A":"Периодически сбрасывает журнал на диск.","B":"Пишет грязные буферы данных, а не журнал.","C":"Выполняет контрольные точки.","D":"Копирует заполненные сегменты в архив."}'),
    ('Чем процесс bgwriter отличается от checkpointer?', '{"A":"Журнал пишет walwriter.","B":"Checkpointer записывает буферы, грязные на начало контрольной точки, обычно растягивая запись во времени.","C":"Упреждающего чтения в кеш bgwriter не делает.","D":"Чтобы у вытесняемых буферов уже была записанная копия."}'),
    ('Какое значение параметра wal_level используется по умолчанию?', '{"A":"Достаточно для восстановления после сбоя, но не для архива WAL и физической репликации.","B":"Подходит для резервного копирования и физической репликации.","C":"Добавляет данные для логической репликации, включается явно.","D":"Старое название; сейчас принимается как синоним replica."}'),
    ('Что защищает журнал предзаписи?', '{"A":"Статусы транзакций тоже журналируются.","B":"В журнал не попадают.","C":"В журнал не попадают.","D":"Изменения страниц таблиц и индексов попадают в журнал."}'),
    ('Какие процессы записывают грязные буферы из буферного кеша на диск?', '{"A":"Заранее пишет буферы, которые скоро вытеснят.","B":"Управляет запуском автоочистки.","C":"Пишет буферы, грязные на начало контрольной точки.","D":"Пишет журнал, а не буферы данных."}'),
    ('Что верно для контрольной точки?', '{"A":"Выполняется периодически: по времени и по объёму журнала.","B":"Записываются все буферы, грязные на начало контрольной точки, в том числе служебные.","C":"Это задача очистки.","D":"У плановых контрольных точек запись распределяется во времени согласно checkpoint_completion_target."}'),
    ('Допишите команду, чтобы узнать текущий уровень журнала:
```
SHOW ___;
```', '{"A":"Уровень журнала предзаписи.","B":"Такого параметра нет.","C":"Такого параметра нет; уровень сообщений задают log_min_messages и client_min_messages.","D":"Такого параметра нет."}'),
    ('Допишите команду, чтобы остановить сервер без контрольной точки, как при сбое:
```
pg_ctl stop -m ___
```', '{"A":"Процессы завершаются сразу, при запуске будет восстановление по журналу.","B":"Такого режима нет.","C":"Отключает клиентов и останавливает сервер корректно, с контрольной точкой.","D":"Ждёт отключения клиентов, затем корректная остановка с контрольной точкой."}'),
    ('Допишите команду, чтобы выполнить контрольную точку вручную:
```
___;
```', '{"A":"Это очистка.","B":"Такой команды SQL нет.","C":"Выполняет контрольную точку немедленно.","D":"Такой команды SQL нет."}'),
    ('Какие базы данных создаются при инициализации кластера?', '{"A":"Создаются ещё два шаблона.","B":"Остальные базы потом создаются клонированием шаблонов.","C":"Создаётся ещё база postgres.","D":"main — имя кластера в Ubuntu, а не базы данных."}'),
    ('Из какой базы по умолчанию клонируется новая база данных?', '{"A":"Используется только при явном указании TEMPLATE template0.","B":"Это обычная база, а не шаблон по умолчанию.","C":"Любая база создаётся клонированием шаблона.","D":"Шаблон по умолчанию."}'),
    ('Для чего нужен шаблон template0?', '{"A":"Чистый шаблон, в котором нет изменений template1.","B":"Роли общие для всего кластера и хранятся не в шаблоне.","C":"По умолчанию подключаются к базе с именем пользователя.","D":"Временные таблицы создаются в той базе, где работает сеанс."}'),
    ('Что такое схема в PostgreSQL?', '{"A":"Схема и пользователь — разные сущности.","B":"Схема — логическое понятие, на диске отдельного каталога у неё нет.","C":"Объекты с одинаковыми именами могут лежать в разных схемах.","D":"Схема находится внутри базы данных."}'),
    ('С объектами каких баз может работать клиент в рамках одного подключения?', '{"A":"Подключение всегда к одной базе.","B":"Табличные пространства на доступ к базам не влияют.","C":"Для другой базы нужно новое подключение.","D":"Даже суперпользователь в одном подключении работает с одной базой."}'),
    ('Как определяется схема объекта, указанного без имени схемы?', '{"A":"Первая схема, где найден объект, и даёт результат.","B":"public используется, только если она есть в пути.","C":"Схема с именем пользователя входит в путь по умолчанию, но не она одна.","D":"Если pg_catalog нет в пути, она неявно просматривается перед ним; поиск идёт по всему пути."}'),
    ('В какую схему попадёт новая постоянная таблица, созданная без указания схемы?', '{"A":"Только если она первая подходящая в пути.","B":"Используется первая подходящая схема, а не последняя.","C":"pg_temp предназначена для временных таблиц.","D":"При этом нужно право CREATE в этой схеме."}'),
    ('Какая функция показывает реальный путь поиска вместе с неявными схемами?', '{"A":"Возвращает только первую схему пути.","B":"С параметром true включает неявные схемы, например pg_catalog.","C":"Такой функции нет.","D":"Такого параметра нет; значение пути — current_setting с search_path."}'),
    ('Что происходит с временной схемой pg_temp_N по окончании сеанса?', '{"A":"Схема потом достаётся другим сеансам.","B":"Схема остаётся и используется другими сеансами.","C":"Временные объекты удаляются при завершении сеанса.","D":"Объекты никуда не переносятся."}'),
    ('Почему работа с временными таблицами быстрее, чем с обычными?', '{"A":"Временные таблицы хранятся в файлах, а не только в кеше ОС.","B":"Ограничения проверяются как обычно.","C":"Используется локальный буфер процесса, журнал не пишется.","D":"Сжимаются только длинные значения через TOAST, как и в обычных таблицах."}'),
    ('Что верно для шаблонов баз данных и базы postgres?', '{"A":"Без базы postgres кластер работает, но некоторые утилиты ждут её наличия.","B":"Если шаблон не указан, используется template1.","C":"По умолчанию используется template1.","D":"Это чистый шаблон, на случай восстановления."}'),
    ('Что верно для пути поиска search_path?', '{"A":"pg_catalog просматривается всегда: если её нет в пути, она неявно добавляется перед ним.","B":"Как и схемы без права USAGE.","C":"Объекты создаются в первой подходящей схеме.","D":"Первая подходящая схема и используется."}'),
    ('Что верно для временных таблиц?', '{"A":"Поэтому работа с ними быстрее.","B":"После сбоя временные таблицы не восстанавливаются.","C":"Другие сеансы их не видят.","D":"Используется локальный буферный кеш процесса."}'),
    ('Допишите команду, чтобы создать базу, в которую рекомендуется восстанавливать копию pg_dump:
```
CREATE DATABASE appdb TEMPLATE ___;
```', '{"A":"TEMPLATE DEFAULT допустимо и выберет template1; для восстановления рекомендуется template0.","B":"Это обычная база, а не шаблон для восстановления.","C":"Чистый шаблон без изменений template1.","D":"Изменения template1 могут конфликтовать с содержимым копии."}'),
    ('Допишите команду, чтобы сначала просматривалась схема app, затем public:
```
SET search_path = ___;
```', '{"A":"Порядок обратный.","B":"В кавычках это одно имя схемы app.public.","C":"Это не список схем: точка не разделяет элементы пути.","D":"Схемы перечисляются через запятую в порядке просмотра."}'),
    ('Допишите команду, чтобы значение действовало во всех новых сеансах базы appdb:
```
ALTER DATABASE appdb ___ temp_buffers = ''32MB'';
```', '{"A":"Такой формы у ALTER DATABASE для параметров нет.","B":"Такого варианта нет.","C":"Такого варианта нет.","D":"Значение по умолчанию для новых сеансов этой базы; настройки роли могут его перекрыть."}')
) AS n(question_text, notes)
WHERE q.question_text = n.question_text AND q.option_notes IS NULL;

UPDATE questions SET question_text = 'На каких уровнях изоляции транзакция может завершиться ошибкой сериализации при обычных изменениях строк (без перемещения строк между секциями)?' WHERE question_text = 'На каких уровнях изоляции транзакция может завершиться ошибкой сериализации?';
UPDATE questions SET question_text = 'Допишите команду, чтобы задать значение по умолчанию для новых сеансов базы appdb:
```
ALTER DATABASE appdb ___ temp_buffers = ''32MB'';
```' WHERE question_text = 'Допишите команду, чтобы значение действовало во всех новых сеансах базы appdb:
```
ALTER DATABASE appdb ___ temp_buffers = ''32MB'';
```';

DO $check$
DECLARE n integer;
BEGIN
    SELECT count(*) INTO n FROM questions WHERE option_notes IS NULL AND category_id IN (SELECT id FROM categories WHERE left(name, 3) IN ('05.', '06.', '07.', '08.'));
    IF n > 0 THEN
        RAISE EXCEPTION 'В темах 05–08 остались вопросы без пояснений к вариантам: %', n;
    END IF;
END
$check$;

COMMIT;
